  KEY `idx_insc_alumno` (`id_alumno`),
  KEY `idx_insc_comision` (`id_comision`),
  CONSTRAINT `inscripcion_alumno_comision_ibfk_1` FOREIGN KEY (`id_alumno`) REFERENCES `alumnos` (`id_alumno`),
  CONSTRAINT `inscripcion_alumno_comision_ibfk_2` FOREIGN KEY (`id_comision`) REFERENCES `comisiones` (`id_comision`)
) ENGINE=InnoDB AUTO_INCREMENT=18001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
