--
-- Table structure for table `inscripciones_finales`
--

DROP TABLE IF EXISTS `inscripciones_finales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inscripciones_finales` (
  `id_inscripcion_final` int NOT NULL AUTO_INCREMENT,
  `id_mesa` int NOT NULL,
  `id_alumno` int NOT NULL,
  `fecha_inscripcion` date DEFAULT NULL,
  `estado` enum('inscripto','presente','ausente','aprobado','desaprobado') DEFAULT NULL,
  `nota` decimal(4,2) DEFAULT NULL,
  PRIMARY KEY (`id_inscripcion_final`),
  UNIQUE KEY `id_mesa` (`id_mesa`,`id_alumno`),
  KEY `idx_insc_final_alumno` (`id_alumno`),
  KEY `idx_insc_final_mesa` (`id_mesa`),
  CONSTRAINT `inscripciones_finales_ibfk_1` FOREIGN KEY (`id_mesa`) REFERENCES `mesas_finales` (`id_mesa`),
  CONSTRAINT `inscripciones_finales_ibfk_2` FOREIGN KEY (`id_alumno`) REFERENCES `alumnos` (`id_alumno`)
) ENGINE=InnoDB AUTO_INCREMENT=22001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

