--
-- Table structure for table `mesas_finales`
--

DROP TABLE IF EXISTS `mesas_finales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mesas_finales` (
  `id_mesa` int NOT NULL AUTO_INCREMENT,
  `id_asignatura` int NOT NULL,
  `id_docente` int NOT NULL,
  `id_aula` int NOT NULL,
  `fecha` date NOT NULL,
  `turno` enum('Febrero','Julio','Diciembre') NOT NULL,
  `llamado` int DEFAULT NULL,
  PRIMARY KEY (`id_mesa`),
  KEY `id_aula` (`id_aula`),
  KEY `idx_mesas_asignatura` (`id_asignatura`),
  KEY `idx_mesas_docente` (`id_docente`),
  KEY `idx_mesas_fecha` (`fecha`),
  CONSTRAINT `mesas_finales_ibfk_1` FOREIGN KEY (`id_asignatura`) REFERENCES `asignaturas` (`id_asignatura`),
  CONSTRAINT `mesas_finales_ibfk_2` FOREIGN KEY (`id_docente`) REFERENCES `docentes` (`id_docente`),
  CONSTRAINT `mesas_finales_ibfk_3` FOREIGN KEY (`id_aula`) REFERENCES `aulas` (`id_aula`)
) ENGINE=InnoDB AUTO_INCREMENT=2501 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
